const US_QUALIFIER = String.raw`(?:us|usa|american|united states)`;
const CLAIMS_US_AUTHORIZATION = new RegExp(
  String.raw`^(?:` +
    String.raw`(?:${US_QUALIFIER} )?citizen(?:ship)?` +
    String.raw`|citizen of (?:the )?${US_QUALIFIER}` +
    String.raw`|(?:${US_QUALIFIER} )?green ?card(?: holder)?` +
    String.raw`|(?:${US_QUALIFIER} |lawful )?permanent resident(?: card)?` +
    String.raw`)$`,
);

/**
 * The candidate's own answer to the US work-authorization pair, when — and only
 * when — the profile states the fact.
 *
 * `eligibility.workAuthorizationUs` is a claim the profile builder writes from
 * the résumé: `"none"` means the person said they have no US work
 * authorization, `""` means nothing established it. Reading `"none"` back as
 * "No" is repeating what the candidate told us, which is the opposite of
 * inventing an answer — and it is what keeps a truthful BR/LATAM candidate from
 * being stopped at the gate on the one US posting they do want.
 *
 * Sponsorship follows from the same fact: someone with no authorization to work
 * in the United States *would* need sponsorship to work there. That is the
 * literal question, and answering it "Yes" is honest. It is not a statement
 * about contractor/EOR arrangements, which are not work performed in the US and
 * which no employer reads out of this field.
 *
 * Anything the profile does not state — an empty field, or a status this
 * function cannot classify — stays blank and unapproved, exactly as before.
 */
function usWorkAuthorizationAnswers(profile: Profile): {
  authorized: string;
  requiresSponsorship: string;
} {
  const raw = (profile.eligibility?.workAuthorizationUs ?? "")
    .trim()
    .toLowerCase();
  if (!raw) return { authorized: "", requiresSponsorship: "" };
  if (raw === "none" || raw === "no") {
    return { authorized: "No", requiresSponsorship: "Yes" };
  }
  if (DENIES_AUTHORIZATION.test(raw)) {
    return { authorized: "", requiresSponsorship: "" };
  }
  // Punctuation and separators carry no meaning here: "u.s. citizen",
  // "green-card", "permanent_resident" are the same three statuses.
  const normalized = raw
    .replace(/\./g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
  if (CLAIMS_US_AUTHORIZATION.test(normalized)) {
    return { authorized: "Yes", requiresSponsorship: "No" };
  }
  // A status we cannot classify (a visa code, a free-text note): the candidate
  // says what it means, not this function.
  return { authorized: "", requiresSponsorship: "" };
}

